def H_for(sig):
    parts=sig.split("|")
    prefix="|".join(parts[:3])
    return KEYMAP.get(hashlib.sha1(prefix.encode("utf-8")).hexdigest()[:16], "H_OTHER")
def main():
    src=ROOT/"data"/"review"/"_dump"/"vml_sigs_23.jsonl"
    if not src.exists():
        print("X run: python scripts/dump_sigs_year.py --entity vml --year 23 --inputs-only"); return
    out=ROOT/"data"/"_overrides"/"vml_horizontal.tsv"; out.parent.mkdir(parents=True,exist_ok=True)
    n=miss=0; dist={}
    with out.open("w",encoding="utf-8") as w:
        for line in src.open(encoding="utf-8"):
            line=line.strip()
            if not line: continue
            sig=json.loads(line)["signature"]; H=H_for(sig)
            if H=="H_OTHER": miss+=1
            w.write(f"{sig}\t{H}\n"); n+=1; dist[H]=dist.get(H,0)+1
    print(f"wrote {out.relative_to(ROOT)}: {n} sigs ({miss} fell to H_OTHER = unmatched prefix)")
    for h,c in sorted(dist.items(),key=lambda x:-x[1]): print(f"  {h:16s} {c}")
if __name__=="__main__": main()
